from pathlib import Path
import subprocess, shutil
ROOT=Path('/root/verge'); OUT=ROOT/'artifacts/verge-tech-20'; FR=OUT/'frames'; OUT.mkdir(parents=True,exist_ok=True)
if FR.exists(): shutil.rmtree(FR)
FR.mkdir()
html=r'''<!doctype html><html><head><style>*{box-sizing:border-box}html,body,#stage{margin:0;width:1920px;height:1080px;overflow:hidden;background:#080a09;color:#edf6f0;font-family:Arial,sans-serif}.s{position:relative;width:100%;height:100%;overflow:hidden;background:radial-gradient(ellipse at 50% 46%,#12372a 0%,#0d1612 38%,#080a09 75%)}.grid{position:absolute;inset:0;opacity:.22;background-image:linear-gradient(rgba(140,255,196,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(140,255,196,.09) 1px,transparent 1px);background-size:72px 72px;mask-image:radial-gradient(ellipse at center,black,transparent 75%)}.e{position:absolute;left:94px;top:78px;font:600 15px monospace;letter-spacing:5px;color:#9de9bd}.foot{position:absolute;bottom:74px;left:94px;right:94px;display:flex;justify-content:space-between;font:600 13px monospace;letter-spacing:3px;color:#6f8879}.center{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);text-align:center}.title{font-size:105px;letter-spacing:-5px;line-height:1.02;font-weight:500;width:1540px}.mint{color:#91efba}.body{margin:30px auto 0;width:870px;font-size:25px;line-height:1.52;color:#b5c4ba}.logo{width:118px;height:118px;border-radius:26px;object-fit:cover;vertical-align:middle;margin-right:25px}.terminal{position:absolute;left:50%;top:50%;width:1260px;height:570px;transform:translate(-50%,-50%);border:1px solid rgba(183,246,207,.22);border-radius:28px;background:rgba(9,14,11,.9);box-shadow:0 35px 100px rgba(0,0,0,.4);overflow:hidden}.bar{height:64px;border-bottom:1px solid rgba(255,255,255,.09);display:flex;align-items:center;padding:0 28px;gap:10px}.dot{width:11px;height:11px;border-radius:50%;background:#6e8979}.file{margin-left:16px;font:600 13px monospace;letter-spacing:2px;color:#a7b6ac}.code{padding:45px 55px;font:23px/1.8 monospace;color:#c6d5cb;white-space:pre}.dim{color:#71867a}.green{color:#91efba}.amber{color:#f1c575}.packet{position:absolute;width:26px;height:26px;border-radius:50%;background:#94f7bf;box-shadow:0 0 45px #59eb98}.node{position:absolute;width:280px;height:230px;border:1px solid rgba(185,247,211,.22);background:rgba(12,19,15,.86);border-radius:30px;display:flex;flex-direction:column;align-items:center;justify-content:center}.node h{font:700 22px monospace;letter-spacing:3px;color:#dcebe2}.node p{margin:14px 22px 0;text-align:center;font:15px/1.5 monospace;color:#8fa398}.trace{position:absolute;height:2px;background:linear-gradient(90deg,transparent,#8ff0b9,transparent)}.badge{display:inline-block;margin-top:25px;border:1px solid rgba(166,245,199,.24);border-radius:999px;padding:12px 18px;font:600 14px monospace;letter-spacing:2px;color:#b6d7c2}.cta{position:absolute;left:50%;top:690px;transform:translateX(-50%);padding:22px 36px;border-radius:14px;background:#9af4c5;color:#07110c;font:700 20px monospace;letter-spacing:2px}</style></head><body><div id="stage"></div><script>const V='./public/verge-logo.jpeg';const C=(x,a,b)=>Math.max(a,Math.min(b,x));const E=x=>{x=C(x,0,1);return x*x*(3-2*x)};const F=(t,a,b)=>E((t-a)/(b-a));const shell=x=>`<div class="s"><div class="grid"></div>${x}<div class="foot"><span>VERGE / x402</span><span>PAYMENTS ARE A PROTOCOL</span></div></div>`;function scene(t){let x='';if(t<3.5){let p=F(t,.2,1),q=F(t,1.3,2.3);x=`<div class="e" style="opacity:${p}">THE MISSING HTTP STATUS</div><div class="center" style="opacity:${p};transform:translate(-50%,-50%) translateY(${24*(1-p)}px)"><div class="title">THE INTERNET KNOWS<br><span class="mint">401. 403. 404.</span></div><div class="body" style="opacity:${q}">But software still needs a native way to pay for a request.</div></div>`}else if(t<7.5){let p=F(t,3.6,4.2),q=F(t,4.4,5.1);x=`<div class="e">01 / CHALLENGE</div><div class="terminal" style="opacity:${p};transform:translate(-50%,-50%) translateY(${20*(1-p)}px)"><div class="bar"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span class="file">GET /api/premium</span></div><div class="code"><span class="dim">HTTP/1.1</span> <span class="amber">402 PAYMENT REQUIRED</span>\n\n<span class="green">X-Pay-Network:</span> robinhood-mainnet\n<span class="green">X-Pay-Token:</span> USDG\n<span class="green">X-Pay-Amount:</span> 0.001\n<span class="green">X-Pay-Recipient:</span> 0x...\n<span class="green">X-Pay-Nonce:</span> 8f3c2d...\n<span class="green">X-Pay-Memo:</span> verge:8f3c2d...</div></div><div class="center" style="top:870px;opacity:${q}"><div class="badge">THE SERVER DEFINES THE PAYMENT REQUEST</div></div>`}else if(t<12.2){let p=F(t,7.6,8.1),d=C((t-8.3)/2.3,0,1),q=F(t,10.6,11.1);x=`<div class="e">02 / VERIFY</div><div class="node" style="left:220px;top:410px;opacity:${p}"><img src="${V}" class="logo" style="margin:0 0 12px"><h>VERGE</h><p>reads the payment proof</p></div><div class="node" style="left:1420px;top:410px;opacity:${p}"><h>ONCHAIN RECEIPT</h><p>USDG Transfer log confirms amount + recipient</p></div><div class="trace" style="left:500px;top:525px;width:930px;opacity:${p}"></div><div class="packet" style="left:${500+900*d}px;top:512px;opacity:${p}"></div><div class="center" style="top:790px;opacity:${q}"><div class="title" style="font-size:65px;width:1100px">VERIFY <span class="mint">SETTLEMENT</span>.<br>NOT A PROMISE.</div></div>`}else if(t<16.4){let p=F(t,12.35,12.9),q=F(t,14.15,14.7);x=`<div class="e">03 / RETRY</div><div class="terminal" style="opacity:${p}"><div class="bar"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span class="file">GET /api/premium + payment proof</span></div><div class="code"><span class="dim">X-Pay-Tx:</span> <span class="green">0x5K4f...3Ax</span>\n<span class="dim">X-Pay-Nonce:</span> <span class="green">8f3c2d...</span>\n\n<span class="green">HTTP/1.1 200 OK</span>\n\n{ <span class="mint">&quot;access&quot;</span>: <span class="mint">&quot;granted&quot;</span> }</div></div><div class="center" style="top:870px;opacity:${q}"><div class="badge">NONCE BOUND · REPLAY REJECTED · ACCESS UNLOCKED</div></div>`}else{let p=F(t,16.6,17.3),q=F(t,17.5,18.1);x=`<div class="e" style="opacity:${p}">VERGE</div><div class="center" style="top:420px;opacity:${p}"><div class="title"><img src="${V}" class="logo">VERGE</div><div class="body" style="opacity:${q}">Give every API a native payment handshake.</div></div><div class="cta" style="opacity:${q}">vergesnowy.com</div>`}return shell(x)}window.seek=t=>stage.innerHTML=scene(t);window.seek(0)</script></body></html>'''
(OUT/'index.html').write_text(html); assets=OUT/'public';
if assets.exists() or assets.is_symlink(): assets.unlink() if assets.is_symlink() else shutil.rmtree(assets)
assets.symlink_to(ROOT/'public',target_is_directory=True)
node='''const {chromium}=require("playwright");(async()=>{const b=await chromium.launch({headless:true});const p=await b.newPage({viewport:{width:1920,height:1080}});await p.goto("file:///root/verge/artifacts/verge-tech-20/index.html");for(let i=0;i<480;i++){await p.evaluate(t=>window.seek(t),i/24);await p.screenshot({path:`/root/verge/artifacts/verge-tech-20/frames/f_${String(i).padStart(4,"0")}.png`})}await b.close()})().catch(e=>{console.error(e);process.exit(1)})'''
(OUT/'render.js').write_text(node)
subprocess.run(['node',str(OUT/'render.js')],cwd=ROOT,check=True)
subprocess.run(['ffmpeg','-y','-framerate','24','-i',str(FR/'f_%04d.png'),'-c:v','libx264','-preset','medium','-crf','17','-pix_fmt','yuv420p',str(OUT/'video.mp4')],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
print(OUT/'video.mp4')
